  name = excluded.name,
  park = excluded.park,
  land = excluded.land,
  logo_path = excluded.logo_path,
  background_path = excluded.background_path,
  attraction_type = excluded.attraction_type,
  duration_minutes = excluded.duration_minutes,
  minimum_height_inches = excluded.minimum_height_inches,
  maximum_height_inches = excluded.maximum_height_inches,
  ages = excluded.ages,
  thrill_types = excluded.thrill_types,
  accessibility = excluded.accessibility,
  warnings = excluded.warnings,
  description = excluded.description,
  photo_pass = excluded.photo_pass,
  lightning_lane = excluded.lightning_lane,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  official_url = excluded.official_url,
  seasonal = excluded.seasonal,
  opening_date = excluded.opening_date;

commit;
